DOCUMENT();

#############
# Load Macros
#############

loadMacros(
  "PGstandard.pl",
  "PGML.pl",
  "AnswerFormatHelp.pl",
  "contextFiniteSolutionSets.pl",
  "contextForm.pl",
  "ORCCA.pl",
  "PGcourse.pl",
);
COMMENT('Authored in PreTeXt');

#######
# Setup
#######

$x = list_random('a'..'n', 'p'..'z', 'A'..'D', 'F'..'N', 'P'..'T', 'V'..'Z');
Context()->variables->are($x => 'Real');
$sol = non_zero_random(-9, 9);
do {
  ($m, $n) = random_subset(2, -9..-1, 1..9);
} until ($n - $m != -1);
($b, $c) = random_subset(2, -9..-1, 1..9);
$d = $n*$sol - ($m*$sol + $b) + $sol + $c;
Context()->noreduce('(-x)-y', '(-x)+y');
$left = Formula("$n $x - ($m $x + $b)")->reduce;
$right = Formula("$d - ($x + $c)")->reduce;
Context("FiniteSolutionSets");
Context()->variables->are($x => 'Real');
$solset = Formula("{$sol}");

#############################
# Exercise Group Introduction
#############################

BEGIN_PGML
Solve the equation.

END_PGML

######
# Body
######

BEGIN_PGML
[`[$left]=[$right]`]

[_]{$solset}{16}

END_PGML

#############
# End Problem
#############

ENDDOCUMENT();
